mapper.select:
SELECT a.* FROM articles a

    INNER JOIN article_tag_rel atr ON a.id = atr.article_id AND atr.tag_id = #{tagId}

WHERE a.status = 'published' AND a.visible = 'public'

    AND a.category_id = #{categoryId}


    AND a.author_id = #{authorId}



    AND (a.publish_time < #{cursorTime} OR (a.publish_time = #{cursorTime} AND a.id < #{cursorId}))


ORDER BY

    a.is_top DESC,

a.publish_time DESC, a.id DESC
LIMIT #{limitSize}

SELECT a.* FROM articles a

    INNER JOIN article_tag_rel atr ON a.id = atr.article_id AND atr.tag_id = #{tagId}

WHERE a.status = 'published' AND a.visible = 'public'

    AND a.category_id = #{categoryId}


    AND a.author_id = #{authorId}



    AND a.publish_time >= #{earliestPublishTime}




    AND (a.rank_score < #{cursorRankScore} OR (a.rank_score = #{cursorRankScore} AND a.id < #{cursorId}))


ORDER BY a.rank_score DESC, a.id DESC
LIMIT #{limitSize}

SELECT a.* FROM articles a

    INNER JOIN article_tag_rel atr ON a.id = atr.article_id AND atr.tag_id IN

        #{item}


WHERE a.id != #{excludeArticleId}
AND a.status = 'published' AND a.visible = 'public'

    AND a.category_id = #{categoryId}

GROUP BY a.id
ORDER BY

    COUNT(atr.tag_id) DESC,

a.publish_time DESC, a.id DESC
LIMIT #{limitSize}
